import subprocess,re,pathlib,collections,sys
ROOT="/tmp/ross-main"
def git(*a,cwd="/tmp/shurik-workspace-hrF2Zw"):
    return subprocess.run(["git","-C",cwd]+list(a),capture_output=True,text=True,check=True).stdout
def messages():
    out={}
    for b in ["rachel","monica","phoebe","joey","chandler","ross"]:
        for sha in git("log","origin/friend/"+b,"--format=%H").split():
            body=git("show","-s","--format=%B",sha)
            if re.search(r'^Friend-Message: 1$',body,re.M):
                ep=re.search(r'^Episode: (.*)$',body,re.M).group(1).strip()
                sp=re.search(r'^Speaker: (.*)$',body,re.M).group(1).strip()
                ts=git("show","-s","--format=%cI",sha).strip()
                u=body[body.find("Reply-To:"):].split("\n\n",1)[1].strip("\n").rstrip()
                out[sha]=(ts,sp,ep,b,u)
    return out
def main():
    msgs=messages()
    trans=collections.defaultdict(set)
    for f in sorted(pathlib.Path(ROOT,"S01").glob("E*.md")):
        for m in re.finditer(r'Source: friend/(\w+) @ ([0-9a-f]{40})',f.read_text()):
            trans[str(f.relative_to(ROOT))].add(m.group(2))
    allt=collections.Counter(s for v in trans.values() for s in v)
    print("messages:",len(msgs))
    byep=collections.Counter(v[2] for v in msgs.values())
    for ep in sorted(byep):
        f=f"S01/E{int(ep[5:]):02d}.md"
        t=trans.get(f,set())
        actual={s for s,v in msgs.items() if v[2]==ep}
        print(f"{ep}: branch={byep[ep]} filed={len(t)} missing={len(actual-t)} unfiled_extra={len(t-actual)}")
    dup={s:c for s,c in allt.items() if c>1}
    if dup: print("DUPLICATES:",dup)
    missing=sorted([(v[0],v[2],v[3],s) for s,v in msgs.items() if s not in allt])
    for m in missing: print("  MISSING",m[0],m[1],m[2],m[3])
main()
