import subprocess,re,pathlib,sys
sys.path.insert(0,"/tmp")
from friends_audit import messages, ROOT
def entry(msgs,sha):
    ts,sp,ep,b,u=msgs[sha]
    return f"**{sp}** ({ts})\n\nSource: friend/{b} @ {sha}\n\n{u}"
def rebuild(path,fnotes=None):
    msgs=messages()
    p=pathlib.Path(ROOT,path); t=p.read_text()
    m=re.match(r"^---\n(.*?)\n---\n\n(.*?)\n\n(.*)$",t,re.S)
    fm,intro,body=m.groups()
    old={}
    for mm in re.finditer(r"\*\*(\w+)\*\* \((.*?)\)\n\nSource: friend/(\w+) @ ([0-9a-f]{40})\n\n(.*?)(?=\n\n\*\*|\n\n\*Editor|\Z)",body,re.S):
        old[mm.group(4)]=mm.group(0).rstrip("\n")
    ep=int(re.search(r'^episode: (\d+)$',fm,re.M).group(1)); epid=f"S01/E{ep:02d}"
    shas=sorted([s for s,v in msgs.items() if v[2]==epid], key=lambda s:(msgs[s][0],s))
    blocks=[entry(msgs,s) for s in shas]
    for sha,block in old.items():
        assert sha in shas, ("dropped",sha)
        assert block in blocks, ("changed",sha)
    newbody="\n\n".join(blocks)
    if fnotes: newbody+="\n\n"+fnotes
    p.write_text(f"---\n{fm}\n---\n\n{intro}\n\n{newbody}\n")
    print(f"{path}: {len(old)} -> {len(blocks)} entries, all preserved")
if __name__=="__main__":
    for path in sys.argv[1:]:
        rebuild(path)
